INSERT INTO `tag` (`name`, `status`) SELECT 'IoT', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'IoT') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Raspberry Pi', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Raspberry Pi') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'iot-training-ite-college-west-staff-january-2018');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('IoT', 'Raspberry Pi', 'WSQ');

